:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.meter {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  border-radius: 8px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 0 0 4px var(--accent), 0 8px 16px rgba(0,0,0,0.5);
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--primary);
  letter-spacing: 1px;
}

.display {
  background: #0a0a15;
  border: 2px solid var(--primary);
  border-radius: 4px;
  padding: 16px;
  margin-bottom: 24px;
  font-size: 1.25rem;
}

.display-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
}

.label {
  color: var(--text-muted);
}

.value {
  font-weight: bold;
  color: var(--accent);
  text-shadow: 0 0 4px var(--accent);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

.btn {
  background: var(--primary);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 4px;
  padding: 12px 20px;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 100px;
}

.btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translateY(2px);
  box-shadow: none;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  border-color: var(--text-muted);
}

.btn.clear {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.btn.clear:hover:not(:disabled) {
  background: #ff6b7a;
}

.max-note {
  text-align: center;
  margin-top: 16px;
  font-size: 0.875rem;
  color: var(--text-muted);
}

@media (max-width: 400px) {
  .meter {
    padding: 16px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.9rem;
    min-width: 80px;
  }
}

'use strict';

const MAX_MINUTES = 180;
const RATE_PER_HOUR = 2.00;

let totalMinutes = 0;

const timeDisplay = document.getElementById('timeDisplay');
const priceDisplay = document.getElementById('priceDisplay');
const add15Btn = document.getElementById('add15');
const add60Btn = document.getElementById('add60');
const clearBtn = document.getElementById('clear');

function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return h + ':' + String(m).padStart(2, '0');
}

function formatPrice(minutes) {
  const price = (minutes / 60) * RATE_PER_HOUR;
  return '$' + price.toFixed(2);
}

function updateDisplay() {
  timeDisplay.textContent = formatTime(totalMinutes);
  priceDisplay.textContent = formatPrice(totalMinutes);
  const atMax = totalMinutes >= MAX_MINUTES;
  add15Btn.disabled = atMax;
  add60Btn.disabled = atMax;
  clearBtn.disabled = totalMinutes === 0;
}

function addMinutes(amount) {
  totalMinutes = Math.min(totalMinutes + amount, MAX_MINUTES);
  updateDisplay();
}

function clearTime() {
  totalMinutes = 0;
  updateDisplay();
}

add15Btn.addEventListener('click', () => addMinutes(15));
add60Btn.addEventListener('click', () => addMinutes(60));
clearBtn.addEventListener('click', clearTime);

updateDisplay();
